                else
                    writer.WriteNull("us_viewers_millions");

            if (episodeUpdate.ViewerRatingOption.IsSet)
                if (episodeUpdate.ViewerRatingOption.Value != null)
                    writer.WriteNumber("viewer_rating", episodeUpdate.ViewerRatingOption.Value!.Value);
                else
                    writer.WriteNull("viewer_rating");

            if (episodeUpdate.WriterOption.IsSet)
                if (episodeUpdate.WriterOption.Value != null)
                    writer.WriteString("writer", episodeUpdate.Writer);
                else
                    writer.WriteNull("writer");
        }
    }
}
